import{_ as a,c as t,o as r,a5 as n}from"./chunks/framework.DorIfSpC.js";const p="/images/silicon-valley-s5/s5-roughcut-v1.mp4",s="/images/silicon-valley-s5/s5-roughcut-v2.mp4",o="/images/silicon-valley-s5/k1-old-vs-new.jpg",i="/images/silicon-valley-s5/greybox-cameras.jpg",l="/images/silicon-valley-s5/direct-models.jpg",c="/images/silicon-valley-s5/nanobanana-vs-gpt.jpg",d="/images/silicon-valley-s5/relight-models.jpg",h="/images/silicon-valley-s5/k4-gpt-redraw.jpg",P=JSON.parse('{"title":"Jackie 的身高，我改了兩次","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/h3-reference-boards"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/h3-reference-boards"}],["meta",{"property":"og:title","content":"Jackie 的身高，我改了兩次 | 星智未來"}],["meta",{"name":"twitter:title","content":"Jackie 的身高，我改了兩次 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Jackie 的身高，我改了兩次\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/h3-reference-boards\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/h3-reference-boards\\"}}"]]},"headers":[],"relativePath":"project/h3-reference-boards.md","filePath":"project/h3-reference-boards.md","lastUpdated":1790608364000}'),m={name:"project/h3-reference-boards.md"};function g(b,e,u,k,y,f){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="jackie-的身高-我改了兩次" tabindex="-1">Jackie 的身高，我改了兩次 <a class="header-anchor" href="#jackie-的身高-我改了兩次" aria-label="Permalink to &quot;Jackie 的身高，我改了兩次&quot;">​</a></h1><blockquote><p>一場教會的戲拍了兩版之後，我發現模型不看劇本，它看你給它的那張圖</p></blockquote><p><strong>作者</strong>：瑞導 <strong>日期</strong>：2026 年 9 月 28 日</p><hr><p>我在 <a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 上自架 MiniMax H3，拍一部十集的橫屏 AI 網路劇《矽谷之戀》。 第一集第五場：男主角 Richard 剛被裁員，被學長拉去華人教會，禮拜後在聚會廳認識三個女生。</p><p>劇本上是這樣：Tony 介紹 Linda、Jenny 和 Jackie，Richard 客氣地笑，Jackie 一直沒說話，最後對他淺淺一笑。 很簡單的一場戲。</p><p>這是第一版：</p><video controls width="100%"><source src="'+p+'" type="video/mp4"></video><p><em>粗剪 v1（9 月 26 日）。不調色、不上字幕的工作版。</em></p><p>看完我寫下的筆記是：<strong>介紹像點名、空間忽大忽小、遠景的臉慘不忍睹、三個女生不像本人。</strong></p><p>我的第一個反應是換模型。花了一個上午查 Seedance、Kling、Veo 最新的狀況，最後得出一個有點丟臉的結論： <strong>這些問題換哪個模型都會發生。</strong> 這就像拍壞了一場戲，第一個念頭是換一台攝影機 —— 但攝影機沒有錯，是我擺的東西不對。</p><p>兩天後的第二版：</p><video controls width="100%"><source src="'+s+'" type="video/mp4"></video><p><em>粗剪 v2（9 月 28 日）。一樣不調色、不上字幕。</em></p><p>中間改了分鏡，但我花最多時間的地方很無聊：<strong>把每一張參考圖重做，而且做到對為止。</strong></p><hr><h2 id="先講一個前提-h3-吃的是一張「板」" tabindex="-1">先講一個前提：H3 吃的是一張「板」 <a class="header-anchor" href="#先講一個前提-h3-吃的是一張「板」" aria-label="Permalink to &quot;先講一個前提：H3 吃的是一張「板」&quot;">​</a></h2><p>H3 有一個模式叫 Ref2VA，你可以餵它幾張參考圖：角色的臉、衣服，還有一張場景圖 —— 我們叫它「板」， 就是這顆鏡頭一開始的畫面：房間長什麼樣、誰站在哪裡。</p><p>我原本以為板只是在交代房間。拍完兩輪我才搞懂：</p><p><strong>板上站的是誰，模型就讓誰演。板上的人長什麼樣，影片裡的人就長什麼樣。</strong></p><p>提示詞管的是「接下來發生什麼」。板管的是「誰、在哪、長怎樣、多高」。 第一版我把九成力氣放在提示詞，問題卻九成出在板上。</p><p>下面是這兩天我講過的筆記，和它們背後真正要改的地方。</p><hr><h2 id="「遠景生成的人臉慘不忍睹」" tabindex="-1">「遠景生成的人臉慘不忍睹」 <a class="header-anchor" href="#「遠景生成的人臉慘不忍睹」" aria-label="Permalink to &quot;「遠景生成的人臉慘不忍睹」&quot;">​</a></h2><p>聚會廳的全景裡，三個女生的臉在畫面上只有二、三十個像素。H3 畫出來的是三個陌生人。</p><p>我一開始的想法是：那就在提示詞裡把臉寫得更清楚。寫了，沒用。又接了她們的臉部參考圖，還是沒用。</p><p>後來查到 MiniMax 自己承認過：<strong>臉小到一定程度，模型就是畫不出特定的人，這是系統級的限制。</strong> 不是我寫得不夠好，是那幾十個像素裝不下一張認得出來的臉。</p><p><strong>所以不要跟它拔河。</strong> 我改成在「生板」的時候就把遠景的人做對： 把那一小區放大，讓圖像模型換臉、換體態，再縮回去貼上。 H3 拿到一張「本來就是她們」的板，就不用靠自己去猜。</p><p><img src="'+o+`" alt="K1 遠景的板：粗剪 v1 用的版本 vs 新版"></p><p><em>左：v1 用的板。右：換臉、依真實身高縮放之後。遠景還是認不出五官，但至少不會「看起來是別人」。</em></p><hr><h2 id="「jenny-比例上太高了」" tabindex="-1">「Jenny 比例上太高了」 <a class="header-anchor" href="#「jenny-比例上太高了」" aria-label="Permalink to &quot;「Jenny 比例上太高了」&quot;">​</a></h2><p>換完臉，新的問題來了：Jenny 比所有人都高，包括 Tony。</p><p>我跟圖像模型說：「讓她的頭頂降到 Tony 眉毛的高度。」 Gemini 很有禮貌地回了一張圖，Jenny 矮了大概一公分。</p><p>⭐ 這是我這兩天最實用的一課：<strong>圖像模型幾乎不聽尺寸的指令。</strong> 它聽得懂「換一件衣服」「拿掉這個人」，聽不懂「矮五公分」。</p><p>最後可靠的做法很土：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 叫模型把她「摳」出來（其他地方全塗成綠色）</span></span>
<span class="line"><span>② 程式依真實身高算縮放比例 —— Jenny 171、Jackie 167、Linda 158 公分</span></span>
<span class="line"><span>③ 腳踩在原地，等比縮小，貼回去</span></span></code></pre></div><p>比例這種事，交給會算數的東西。</p><hr><h2 id="「506-的-jackie-比-jenny-高-要調整」" tabindex="-1">「506 的 Jackie 比 Jenny 高，要調整」 <a class="header-anchor" href="#「506-的-jackie-比-jenny-高-要調整」" aria-label="Permalink to &quot;「506 的 Jackie 比 Jenny 高，要調整」&quot;">​</a></h2><p>然後我改了。</p><h2 id="「506-jackie-還是太高」" tabindex="-1">「506 Jackie 還是太高」 <a class="header-anchor" href="#「506-jackie-還是太高」" aria-label="Permalink to &quot;「506 Jackie 還是太高」&quot;">​</a></h2><p>然後我又改了一次。</p><p>第一次我讓她只比 Jenny 矮一點點（畫面上低 10 個像素），因為照身高算，她只比 Jenny 矮 4 公分。 但 Jackie 站得離鏡頭最近，<strong>透視會讓她看起來比實際高</strong>，H3 生成時又順手把她拉高了一點。 第二次直接降了半顆頭，才終於看起來對。</p><p><strong>真實身高是一回事，畫面上看起來的高度是另一回事。</strong> 觀眾只看得到後面那個。</p><hr><h2 id="「不要用點名的方式來拍」" tabindex="-1">「不要用點名的方式來拍」 <a class="header-anchor" href="#「不要用點名的方式來拍」" aria-label="Permalink to &quot;「不要用點名的方式來拍」&quot;">​</a></h2><p>第一版的介紹是 Tony 站在中間，一個一個指著說「這是 Linda、這是 Jenny」。 很像開學第一天。</p><p>我要的是 Richard 的眼睛：他走過去，先看到三個女生的背影，她們轉過來，然後鏡頭慢慢推近每一個人。</p><p>這一次我沒有直接寫提示詞，而是先回到平面圖：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平面圖（牆、窗、椅子、每個人站哪、每個機位在哪）</span></span>
<span class="line"><span>  → Blender 灰模（同一份座標，每個機位算一張圖）</span></span>
<span class="line"><span>    → 圖像模型把灰模變成寫實的板</span></span>
<span class="line"><span>      → H3 拿板當第一格</span></span></code></pre></div><p><img src="`+i+'" alt="四個新機位的灰模"></p><p><em>灰模裡每一根圓柱就是一個人，顏色是那個角色的衣服。</em></p><p>灰模很醜，但它讓我在花任何算力之前，就看到「這個機位 Jackie 會被 Jenny 整個擋住」。 在平面圖上挪一個座標是幾秒鐘的事；等 H3 拍完才發現，是一次開機、一次算圖、一次看片。</p><p>⭐ 八月我寫過〈<a href="./storyboard-before-render">我把上一篇刪掉的那一步，加了回來</a>〉，講的是算圖之前先生分鏡圖。 這一場讓我確定：<strong>板就是分鏡圖，只是它同時也是模型的輸入。</strong></p><hr><h2 id="「image-2-較自然」" tabindex="-1">「image-2 較自然」 <a class="header-anchor" href="#「image-2-較自然」" aria-label="Permalink to &quot;「image-2 較自然」&quot;">​</a></h2><p>有了灰模，下一步是把它變成寫實的板。這次我沒有只用平常的 Gemini， 而是拿同一組輸入 —— 灰模、四張臉、三張服裝圖 —— 讓五個圖像模型各生一次：</p><p><img src="'+l+`" alt="同一組灰模＋臉＋服裝，五個模型直出的對照"></p><p><em>每一列是一個機位，每一欄是一個模型。</em></p><p>差別比我預期的大：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gemini（flash、Nano Banana Pro）  鏡頭會自己往後退，灰模裡的近景守不住</span></span>
<span class="line"><span>GPT（image-2、2.5 flare、2.5 sunburst） 照灰模的近景走，臉也最像本人</span></span></code></pre></div><p>GPT 的三個裡，最新的 2.5 有一個可愛的毛病：我餵了一張三個女生的服裝示意圖， 圖裡的人背著包包 —— 2.5 就把包包也一起帶來了。像去喝喜酒，順手把隔壁桌的伴手禮也拿走。</p><p>最後選的是 <strong>gpt-image-2</strong>。不是最新的，但最自然。</p><p>不過也不是一律用 GPT。全廳的俯角遠景，Nano Banana Pro 反而最好：</p><p><img src="`+c+'" alt="遠景用 Nano Banana Pro，近景用 gpt-image-2"></p><p><em>第一列是俯角全景，Nano Banana Pro 最自然；其餘三列要的是近景，GPT 比較好。</em></p><p>⭐ <strong>沒有「最好的模型」，只有「這一格最適合的模型」。</strong> 比一次的成本很低，一張板台幣幾塊錢； 板錯了的成本很高 —— 錯的是用到這張板的每一顆鏡頭。</p><hr><h2 id="「臉上的光整體不搭」" tabindex="-1">「臉上的光整體不搭」 <a class="header-anchor" href="#「臉上的光整體不搭」" aria-label="Permalink to &quot;「臉上的光整體不搭」&quot;">​</a></h2><p>換臉這一步有個副作用：參考照是棚拍的正面平光，換到一個逆光的房間裡，臉亮得像打了補光燈。</p><p>同一段補光指令，我比了五個模型：</p><p><img src="'+d+'" alt="補光：Gemini 與四個 GPT 圖像模型"></p><p><em>gpt-image-1.5 把整塊都變暗了；gpt-image-2 和兩個 2.5 版本保住了窗戶的亮度，臉也不再像棚拍。這一步我選了 2.5 flare。</em></p><p>有一張板（四個人圍成一圈），我乾脆讓 gpt-image-2 以舊板為底整張重畫，光一次統一：</p><p><img src="'+h+'" alt="K4：以舊板為底，GPT 整張重畫"></p><p><em>右下是採用的版本。左下是讓 GPT 直接從灰模生 —— 它沒照灰模走，四個人又排成一排了。</em></p><hr><h2 id="「richard-身穿深灰衣服-506-的背影顏色不對」" tabindex="-1">「Richard 身穿深灰衣服，506 的背影顏色不對」 <a class="header-anchor" href="#「richard-身穿深灰衣服-506-的背影顏色不對」" aria-label="Permalink to &quot;「Richard 身穿深灰衣服，506 的背影顏色不對」&quot;">​</a></h2><p>這是我這兩天最喜歡的一條筆記。</p><p>506 是 Richard 的主觀鏡頭：他走向那一圈人。H3 很貼心地在畫面左前方補了一個肩膀 —— 它覺得既然是某個人在走，那總得有個人。</p><p>然後它<strong>自己幫 Richard 挑了一件淺藍襯衫</strong>。</p><p>Richard 這場穿的是炭灰毛衣。但我在 506 的提示詞裡沒寫他，因為我以為他「不在畫面裡」。 <strong>模型不會替你想你沒寫的事 —— 但它會替你決定。</strong></p><hr><h2 id="所以這兩版差在哪" tabindex="-1">所以這兩版差在哪 <a class="header-anchor" href="#所以這兩版差在哪" aria-label="Permalink to &quot;所以這兩版差在哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我說</th><th>真正要改的地方</th></tr></thead><tbody><tr><td>遠景的臉慘不忍睹</td><td>不改提示詞，改板：放大換臉再縮回去</td></tr><tr><td>Jenny 太高</td><td>不跟模型講公分，用程式等比縮放</td></tr><tr><td>Jackie 還是太高</td><td>看的是畫面上的高度，不是身分證上的</td></tr><tr><td>不要點名</td><td>先回平面圖和灰模，重排機位</td></tr><tr><td>image-2 較自然</td><td>同一組輸入比五個模型，每一格挑適合的</td></tr><tr><td>背影顏色不對</td><td>畫面裡可能出現的人，都要交代他穿什麼</td></tr></tbody></table><p>⭐ 左邊是我看片時的直覺，右邊幾乎都不在「寫提示詞」這一格。 第一版我在問「哪個影片模型比較強」，第二版我在問「我給它的第一格對不對」。 後面那個問題便宜得多，而且答得出來。</p><p><strong>如果只能帶走一句</strong>：</p><blockquote><p>模型不看劇本，它看板。 先把板生對，再來拍。</p></blockquote><hr><p><em>本文的環境：<a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 租用之 GPU，MiniMax H3 剪枝 INT8 開源權重， 於 ComfyUI 部署，Ref2VA、8 步 PDD 加速，輸出 1376 × 768。生板用 gpt-image-2（近景）、 Nano Banana Pro（遠景）、gpt-image-2.5-flare（補光）、Gemini flash（局部修改）；灰模用 Blender。</em></p><p><em>每天的進度、失敗與抽格我都貼在脆上：<a href="https://www.threads.com/share/GfotsoXNd/" target="_blank" rel="noreferrer">瑞導</a> —— 那邊是當天的原始紀錄，這裡是想清楚之後的版本。</em></p><p><em>分鏡先於算圖的理由見<a href="./storyboard-before-render">〈我把上一篇刪掉的那一步，加了回來〉</a>。</em></p><p><em>本文的 RunPod 連結為推薦連結，透過它註冊我會獲得少量回饋，不影響你的價格。</em></p><p><em><a href="https://aidream.com.tw" target="_blank" rel="noreferrer">aidream.com.tw</a></em></p>',95)])])}const J=a(m,[["render",g]]);export{P as __pageData,J as default};
